using System;
using System.IO;
using System.IO.Compression;
using System.Diagnostics;
using System.Reflection;
using System.Text;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class GameVersionProbeTests {
  static int checks;static Type api;
  static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);checks++;}
  static Version Read(string path){return (Version)api.GetMethod("Read").Invoke(null,new object[]{path});}
  static void Put(string file,string text){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,text,new UTF8Encoding(false));}
  static void Jar(string game,byte[] bytes){Directory.CreateDirectory(game);string path=Path.Combine(game,"projectzomboid.jar");if(File.Exists(path))File.Delete(path);using(var archive=ZipFile.Open(path,ZipArchiveMode.Create)){using(var stream=archive.CreateEntry("zombie/core/Core.class").Open())stream.Write(bytes,0,bytes.Length);}}
  static byte[] Compile(string root,string expression){string source=Path.Combine(root,"src/zombie/core/Core.java");Put(source,"package zombie.core; public class Core { public static GameVersion gameVersion; static { gameVersion = "+expression+"; } public static GameVersion getBreakMod(){return new GameVersion(42,0,\"\");} } class GameVersion { public GameVersion(int major,int minor,String suffix){} public GameVersion(String unknown){} }");string output=Path.Combine(root,"classes");Directory.CreateDirectory(output);var start=new ProcessStartInfo("C:/Program Files/Microsoft/jdk-21.0.12.101-hotspot/bin/javac.exe","-encoding UTF-8 -d \""+output+"\" \""+source+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};using(var p=Process.Start(start)){string error=p.StandardError.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception("Fixture javac: "+error);}return File.ReadAllBytes(Path.Combine(output,"zombie/core/Core.class"));}
  public static int Main(){try{Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
public static void Run(){api=typeof(Engine).Assembly.GetType("PZ3D.GameVersionProbe");Check(api!=null,"read-only classfile version probe exists");string root=Path.Combine(LauncherTestPaths.Root,"orange-version-"+Guid.NewGuid().ToString("N"));try{string game=Path.Combine(root,"game");Check(Read(game)==null,"absent version jar is unknown");byte[] literal=Compile(root,"new GameVersion(42,21,\"\")");Jar(game,literal);Check(Read(game).Equals(new Version(42,21)),"typed clinit literal yields 42.21 instead of other method's 42.0");byte[] jarBefore=File.ReadAllBytes(Path.Combine(game,"projectzomboid.jar"));Check(Read(game).Equals(new Version(42,21))&&jarBefore.SequenceEqual(File.ReadAllBytes(Path.Combine(game,"projectzomboid.jar"))),"version probe keeps exact jar bytes unchanged");Jar(game,Compile(root,"new GameVersion(42,21,\"\\000\")"));Check(new Version(42,21).Equals(Read(game)),"JVM modified UTF8 suffix remains a valid typed string literal");foreach(int minor in new[]{4,300,40000}){Jar(game,Compile(root,"new GameVersion(42,"+minor+",\"\")"));Check(new Version(42,minor).Equals(Read(game)),"iconst sipush and ldc integer forms parsed");}Jar(game,Compile(root,"new GameVersion(\"unknown\")"));Check(Read(game)==null,"unknown constructor never chooses non-clinit version");foreach(byte[] invalid in new[]{new byte[0],literal.Take(15).ToArray(),literal.Take(literal.Length-1).ToArray(),new byte[]{0,0,0,0},new byte[2097153]}){Jar(game,invalid);Check(Read(game)==null,"invalid truncated oversized class remains unknown");}Jar(game,literal);string user=Path.Combine(root,"user");var engine=new Engine(game,user,Path.Combine(root,"data"),true);Put(Path.Combine(user,"mods/Minor/42.13/mod.info"),"id=MinorOnly\nname=Available\n");Put(Path.Combine(user,"mods/Future/42.99/mod.info"),"id=FutureOnly\n");var json=new JavaScriptSerializer();var catalog=json.Deserialize<Dictionary<string,object>>(json.Serialize(SaveProfiles.Catalog(engine)));var rows=((ArrayList)catalog["mods"]).Cast<Dictionary<string,object>>().ToArray();Check(rows.Any(r=>(string)r["id"]=="MinorOnly")&&!rows.Any(r=>(string)r["id"]=="FutureOnly"),"catalog uses read-only 42.21 probe to select 42.13 and exclude 42.99");Console.WriteLine("GameVersionProbe PASS: "+checks+" assertions");}finally{string cleanup=Path.GetFullPath(root);string tempRoot=Path.GetFullPath(LauncherTestPaths.Root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string leaf=Path.GetFileName(cleanup);if(!cleanup.StartsWith(tempRoot,StringComparison.OrdinalIgnoreCase)||!System.Text.RegularExpressions.Regex.IsMatch(leaf,@"^orange-version-[0-9a-f]{32}$"))throw new IOException("Unsafe test cleanup path");if(Directory.Exists(cleanup))Directory.Delete(cleanup,true);}}
 }
}
